import { config } from '@hexa-ui/theme';
import type * as Stitches from '@stitches/react';

type CSSVariants = Stitches.CSS<typeof config>;

export interface ImageTypes extends React.ImgHTMLAttributes<HTMLImageElement> {
  containerCss?: CSSVariants;
  src: string;
  aspectRatio?: number;
  // Ideally aspect ratio will be used as a fraction. Example: 16 / 9.
  variant?: 'fill' | 'fit' | 'stretch';
  position?: string;
  // Position will recieve two parameters heigt and width. Example: '10% 50%'
  isInteractive?: boolean;
  disabled?: boolean;
  customErrorImage?: customErrorImage;
}

export type customErrorImage = {
  width?: string;
  height?: string;
  src: string;
  alt: string;
};
